const allItems = $input.all();
if (allItems.length === 0) {
  return [{ json: { error: 'No data' } }];
}

const midPoint = Math.floor(allItems.length / 2);
const currentMonth = allItems.slice(0, midPoint);
const lastMonth = allItems.slice(midPoint);

const lastMonthMap = new Map();
for (const item of lastMonth) {
  const row = item.json;
  const res = (row.Resource || '').trim();
  if (res) {
    lastMonthMap.set(res, parseFloat(row.CostUSD || 0));
  }
}

const results = [];
const processed = new Set();

for (const item of currentMonth) {
  const row = item.json;
  const res = (row.Resource || '').trim();
  if (!res) continue;

  const curr = parseFloat(row.CostUSD || 0);
  const last = lastMonthMap.get(res) || 0;
  const diff = curr - last;

  let remark = '';
  if (last === 0) {
    remark = 'New';
  } else if (diff === 0) {
    remark = 'No change';
  } else {
    const pct = ((diff / last) * 100).toFixed(2);
    remark = (diff > 0 ? '+' : '') + diff.toFixed(2) + ' USD (' + pct + '%)';
  }

  results.push({
    ResourceGroup: row.ResourceGroup || '',
    Resource: res,
    ResourceType: row.ResourceType || '',
    ResourceLocation: row.ResourceLocation || '',
    'Last Month': last.toFixed(2),
    'Current Month': curr.toFixed(2),
    Difference: diff.toFixed(2),
    Remark: remark
  });
  processed.add(res);
}

for (const [res, cost] of lastMonthMap.entries()) {
  if (!processed.has(res)) {
    results.push({
      ResourceGroup: '',
      Resource: res,
      ResourceType: '',
      ResourceLocation: '',
      'Last Month': cost.toFixed(2),
      'Current Month': '0.00',
      Difference: (-cost).toFixed(2),
      Remark: 'Deleted'
    });
  }
}

results.sort((a, b) => {
  const ord = (r) => r === 'New' ? 1 : r === 'Deleted' ? 2 : r.includes('USD') ? 3 : 4;
  const diff = ord(a.Remark) - ord(b.Remark);
  return diff !== 0 ? diff : Math.abs(parseFloat(b.Difference)) - Math.abs(parseFloat(a.Difference));
});

return results.map(r => ({ json: r }));
